711	// ListShifts 返回全部班次，按编号排序。
712	func (svc *Service) ListShifts() []Shift {
713		out := append([]Shift(nil), svc.store.data.Shifts...)
714		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
715		return out
716	}
