	}
	if strings.Contains(text1, "尚未处理") || strings.Contains(text1, "0001-01-01") {
		t.Fatalf("已处理事项不能显示成尚未处理或公元元年：\n%s", text1)
	}

	// 继续跟踪但处理人为空、处理时间为零值：两者各自标为未记录，
	// 跟踪说明与当时指定的负责人仍按原记录展示。
